create table feedx_integrations.navigation_modules(
 id text primary key, workspace text not null check(workspace='Factory'), section text not null,label text not null,route text not null,
 sidebar boolean not null,coverage text not null check(coverage in ('available','partial','unavailable')),explanation text not null,sort_order integer not null
);
create table feedx_integrations.navigation_resources(
 module_id text not null references feedx_integrations.navigation_modules(id),resource_key text not null references feedx_integrations.resources(key),
 row_scope jsonb not null default '{}',allowed_fields jsonb not null,relationship_modules jsonb not null default '{}',required_modules jsonb not null default '[]',
 primary key(module_id,resource_key)
);
alter table feedx_integrations.navigation_modules enable row level security;
alter table feedx_integrations.navigation_resources enable row level security;
revoke all on feedx_integrations.navigation_modules,feedx_integrations.navigation_resources from public,anon,authenticated;
alter table feedx_integrations.capabilities add column navigation_module_id text references feedx_integrations.navigation_modules(id);
create unique index capabilities_navigation_action on feedx_integrations.capabilities(navigation_module_id,action_type) where navigation_module_id is not null;


