create function feedx_integrations.navigation_has_module(p_token text,p_module text) returns boolean language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_id uuid;begin
 v_id:=feedx_integrations.authorize(p_token,'factory_mesti_inspection.view');
 return exists(select 1 from feedx_integrations.machine_identities m join feedx_integrations.capabilities c on c.adapter_key=m.adapter_key join feedx_integrations.navigation_modules n on n.id=c.navigation_module_id join public.permissions p on p.code=c.permission_code join public.role_permissions rp on rp.role_id=m.role_id and rp.permission_id=p.id where m.id=v_id and n.id=p_module and n.coverage<>'unavailable' and c.implemented and c.action_type='view' and not c.requires_human_approval);
 exception when insufficient_privilege then return false;end $$;
revoke all on function feedx_integrations.navigation_has_module(text,text) from public,anon,authenticated;
create function feedx_integrations.navigation_authorize(p_token text,p_module text,p_resource text) returns uuid language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_id uuid;v_required jsonb;dep text;begin
 v_id:=feedx_integrations.authorize(p_token,'factory_mesti_inspection.view');
 if not feedx_integrations.navigation_has_module(p_token,p_module) then raise exception using errcode='42501',message='Business module access denied.';end if;
 select b.required_modules into v_required from feedx_integrations.navigation_resources b join feedx_integrations.resources r on r.key=b.resource_key where b.module_id=p_module and r.slug=p_resource and r.implemented;
 if not found then raise exception using errcode='42501',message='Resource is outside this business module.';end if;
 for dep in select jsonb_array_elements_text(v_required) loop
  if not feedx_integrations.navigation_has_module(p_token,dep) then raise exception using errcode='42501',message='Summary requires its contributing business modules.';end if;
 end loop;return v_id;end $$;
revoke all on function feedx_integrations.navigation_authorize(text,text,text) from public,anon,authenticated;


create or replace function feedx_integrations.read_permission(p_token text,p_permission text) returns boolean language plpgsql stable security invoker set search_path=public,pg_temp as $$ declare r text;m text;begin if p_token is null then return public.current_user_has_permission(p_permission);end if; r:=case p_permission when 'factory_dashboard.view' then 'dashboard' when 'factory_production.view' then 'production_records' when 'factory_production_reports.view' then 'production_records' when 'factory_job_orders.view' then 'job_orders' when 'factory_finished_goods_dispatch.view' then 'dispatches' when 'factory_raw_receiving.view' then 'receipts' when 'factory_raw_inventory.view' then 'raw_materials' when 'factory_finished_goods.view' then 'finished_goods' when 'factory_batch_traceability.view' then 'traceability' when 'factory_raw_stock_check.view' then 'raw_stock_checks' when 'factory_product_stock_check.view' then 'product_stock_checks' end;m:=case p_permission when 'factory_dashboard.view' then 'factory_dashboard' when 'factory_production.view' then 'factory_production' when 'factory_production_reports.view' then 'factory_production_reports' when 'factory_job_orders.view' then 'factory_job_order_records' when 'factory_finished_goods_dispatch.view' then 'factory_finished_goods_dispatch' when 'factory_raw_receiving.view' then 'factory_raw_receiving' when 'factory_raw_inventory.view' then 'factory_raw_inventory' when 'factory_finished_goods.view' then 'factory_finished_goods' when 'factory_batch_traceability.view' then 'factory_batch_traceability' when 'factory_raw_stock_check.view' then 'factory_raw_stock_check' when 'factory_product_stock_check.view' then 'factory_product_stock_check' end;if r is null then return false;end if;return feedx_integrations.navigation_has_module(p_token,m) or feedx_integrations.has_resource(p_token,r);end $$;

create or replace function feedx_integrations.resource_query_validate(p_query jsonb) returns jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare q jsonb;v_key text;v_value jsonb;v_from date;v_to date;v_limit integer;v_filters jsonb;
begin
 if jsonb_typeof(p_query) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_query) k where k not in ('resource','action','date_range','module','business_module','id','search','filters','limit','cursor')) then raise exception using errcode='22023',message='Unsupported query fields.';end if;
 if p_query->>'resource' is null or p_query->>'action' is null or p_query->>'action' not in ('list','read','search','filter') then raise exception using errcode='22023',message='Specify a resource and read operation.';end if;
 if jsonb_typeof(p_query->'date_range') is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_query->'date_range') k where k not in ('from','to'))
 or coalesce(p_query->'date_range'->>'from','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(p_query->'date_range'->>'to','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception using errcode='22023',message='A bounded Malaysia date range is required.';end if;
 v_from:=(p_query->'date_range'->>'from')::date;v_to:=(p_query->'date_range'->>'to')::date;
 if v_to<v_from or v_to-v_from>30 then raise exception using errcode='22023',message='Use at most 31 business dates.';end if;
 if p_query ? 'module' and (jsonb_typeof(p_query->'module')<>'string' or p_query->>'module' not in ('cleaning_of_area','cleaning_of_equipment','calibration','operator_hygiene','waste_disposal','health_declaration','food_processing_control','finished_product_storage_control')) then raise exception using errcode='22023',message='Unsupported MeSTI module.';end if;
 if p_query ? 'limit' and (jsonb_typeof(p_query->'limit')<>'number' or (p_query->>'limit') !~ '^[0-9]{1,3}$') then raise exception using errcode='22023',message='Use an integer page size from 1 to 100.';end if;
 v_limit:=coalesce((p_query->>'limit')::integer,50);
 if v_limit not between 1 and 100 then raise exception using errcode='22023',message='Use a page size from 1 to 100.';end if;
 if p_query ? 'cursor' and (jsonb_typeof(p_query->'cursor')<>'string' or length(p_query->>'cursor') not between 1 and 2048 or p_query->>'cursor' !~ '^[A-Za-z0-9+/]+={0,2}$') then raise exception using errcode='22023',message='Invalid page cursor.';end if;
 if p_query->>'action'='read' then
  if jsonb_typeof(p_query->'id') is distinct from 'string' or length(p_query->>'id') not between 1 and 240 or p_query ?| array['search','filters','cursor','limit'] then raise exception using errcode='22023',message='Read requires one resource ID and no collection operations.';end if;
 elsif p_query ? 'id' then raise exception using errcode='22023',message='Use the Read operation for a resource ID.';end if;
 if p_query->>'action'='search' then
  if jsonb_typeof(p_query->'search') is distinct from 'string' or length(trim(p_query->>'search')) not between 1 and 100 then raise exception using errcode='22023',message='Search requires 1 to 100 characters.';end if;
 elsif p_query ? 'search' then raise exception using errcode='22023',message='Use the Search operation for search text.';end if;
 if p_query->>'action'='filter' then
  if jsonb_typeof(p_query->'filters') is distinct from 'object' or p_query->'filters'='{}'::jsonb then raise exception using errcode='22023',message='Filter requires supported fields.';end if;
  select filter_fields into v_filters from feedx_integrations.resources where adapter_key='factory_mesti' and slug=p_query->>'resource' and implemented;
  for v_key,v_value in select * from jsonb_each(p_query->'filters') loop
   if not coalesce(v_filters ? v_key,false) or jsonb_typeof(v_value)<>'string' or length(v_value#>>'{}') not between 1 and 240 then raise exception using errcode='22023',message='Unsupported filter field or value.';end if;
  end loop;
 elsif p_query ? 'filters' then raise exception using errcode='22023',message='Use the Filter operation for structured filters.';end if;
 q:=p_query||jsonb_build_object('limit',case when p_query->>'action'='read' then 1 else v_limit end);
 return q;
exception when invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then raise exception using errcode='22023',message='Invalid bounded query values.';
end $$;
revoke all on function feedx_integrations.resource_query_validate(jsonb) from public,anon,authenticated;





create function feedx_integrations.navigation_validate(p_token text,p_query jsonb) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare b feedx_integrations.navigation_resources%rowtype;q jsonb;f text;begin
 q:=feedx_integrations.resource_query_validate(p_query);
 select x.* into strict b from feedx_integrations.navigation_resources x join feedx_integrations.resources r on r.key=x.resource_key where x.module_id=q->>'business_module' and r.slug=q->>'resource';
 if b.row_scope ? 'module' then
  if q ? 'module' and q->>'module' is distinct from b.row_scope->>'module' then raise exception using errcode='22023',message='Conflicting module scope.';end if;
  if q->'filters' ? 'module' and q->'filters'->>'module' is distinct from b.row_scope->>'module' then raise exception using errcode='22023',message='Conflicting module filter.';end if;
  q:=q||jsonb_build_object('module',b.row_scope->>'module');
 elsif q ? 'module' then raise exception using errcode='22023',message='Module filter is not supported here.';end if;
 for f in select jsonb_object_keys(coalesce(q->'filters','{}')) loop
  if not b.allowed_fields ? f or (b.relationship_modules ? f and not feedx_integrations.navigation_has_module(p_token,b.relationship_modules->>f)) then raise exception using errcode='22023',message='Filter is outside the authorized module fields.';end if;
 end loop;return q;end $$;
revoke all on function feedx_integrations.navigation_validate(text,jsonb) from public,anon,authenticated;


create function feedx_integrations.audit_navigation_owner(p_action text) returns text language sql immutable set search_path=public,pg_temp as $$
 select case
 when p_action ~ '^factory_mesti_cleaning' then 'factory_mesti_cleaning'
 when p_action ~ '^factory_mesti_equipment_cleaning' then 'factory_mesti_equipment_cleaning'
 when p_action ~ '^factory_mesti_calibration' then 'factory_mesti_calibration'
 when p_action ~ '^factory_mesti_waste_disposal' then 'factory_mesti_waste_disposal'
 when p_action ~ '^factory_qc_template' then 'factory_production_sop'
 when p_action ~ '^factory_(product_group|product_family)' then 'factory_product_recipes'
 when p_action ~ '^factory_historical_dispatch_batch_reconciled' then 'factory_batch_traceability'
 when p_action ~ '^factory_(raw_material_stock_check|raw_stock_check)' then 'factory_raw_stock_check'
 when p_action ~ '^factory_product_stock_check' then 'factory_product_stock_check'
 when p_action ~ '^factory_(raw_material_receiv|raw_receiv)' then 'factory_raw_receiving'
 when p_action ~ '^factory_finished_good_dispatch' then 'factory_finished_goods_dispatch'
 when p_action ~ '^factory_internal_transfer' then 'factory_internal_transfer'
 when p_action ~ '^factory_job_order' then 'factory_job_order_records'
 when p_action ~ '^factory_production_(sop|procedure)' then 'factory_production_sop'
 when p_action ~ '^factory_(product_recipe|recipe)' then 'factory_product_recipes'
 when p_action ~ '^factory_(production|qc)' then 'factory_production'
 when p_action ~ '^factory_raw_material' then 'factory_raw_inventory'
 when p_action ~ '^factory_finished_good' then 'factory_finished_goods'
 when p_action ~ '^factory_(supplier)' then 'factory_suppliers'
 when p_action ~ '^factory_(customer)' then 'factory_customers'
 when p_action ~ '^factory_(storage_location|location)' then 'factory_storage_locations'
 when p_action ~ '^factory_equipment' then 'factory_equipment'
 when p_action ~ '^factory_petty_cash' then 'factory_petty_cash'
 when p_action ~ '^factory_product_feedback' then 'factory_product_feedback'
 end;
$$;
revoke all on function feedx_integrations.audit_navigation_owner(text) from public,anon,authenticated;
create function feedx_integrations.navigation_audit_rows(p_from date,p_to date) returns setof jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',r.id,'label',r.event_label,'module',r.module_label,'action',r.action,'result',r.result,'attention_required',r.attention_required,'created_at',r.created_at) from public.factory_audit_trail_rows()r where (r.created_at at time zone 'Asia/Kuala_Lumpur')::date between p_from and p_to;
$$;
revoke all on function feedx_integrations.navigation_audit_rows(date,date) from public,anon,authenticated;


create or replace function feedx_integrations.factory_resource_rows(p_token text,p_resource text,p_from date,p_to date) returns setof jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$ declare v_count integer;begin case p_resource

when 'job_orders' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Job Orders','business_date',s.business_date) - 'safe_label' from (select r.id,r.job_order_no,r.target_pack_qty,r.target_production_qty,r.target_quantity,r.produced_quantity,r.uom,r.planned_date,r.due_date,r.priority,r.status,r.released_at,r.started_at,r.production_date,r.start_time,r.completed_at,r.finished_good_id,r.production_sop_id,r.sop_version,r.job_order_no safe_label,r.planned_date business_date from public.factory_job_orders r where (r.planned_date) between p_from and p_to limit 5001)s;

when 'production_records' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Production','business_date',s.business_date) - 'safe_label' from (select r.id,r.production_no,r.batch_no,r.job_order_id,r.finished_good_id,r.actual_pack_qty,r.actual_output_qty,r.produced_quantity,r.actual_produced_qty,r.good_output_qty,r.wastage_qty,r.uom,r.production_date,r.manufacturing_date,r.end_date,r.expiry_date,r.start_time,r.end_time,r.qc_status,r.production_sop_id,r.sop_version,r.status,r.completed_at,r.verification_status,r.verified_at,r.storage_location_id,r.production_no safe_label,case when r.status='completed' then r.end_date else r.production_date end business_date from public.factory_productions r where (case when r.status='completed' then r.end_date else r.production_date end) between p_from and p_to limit 5001)s;

when 'execution_steps' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Production','business_date',s.business_date) - 'safe_label' from (select r.id,r.job_order_id,r.production_id,r.step_no,r.step_name,r.status,r.completed_at,r.step_name safe_label,(r.created_at at time zone 'Asia/Kuala_Lumpur')::date business_date from public.factory_production_step_executions r where ((r.created_at at time zone 'Asia/Kuala_Lumpur')::date) between p_from and p_to limit 5001)s;

when 'qc_results' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Production','business_date',s.business_date) - 'safe_label' from (select r.id,r.job_order_id,r.production_id,r.production_step_execution_id,r.sequence_no,r.qc_type,r.qc_name,r.is_required,r.checklist_result,r.checked_at,r.qc_name safe_label,(r.created_at at time zone 'Asia/Kuala_Lumpur')::date business_date from public.factory_production_qc_results r where ((r.created_at at time zone 'Asia/Kuala_Lumpur')::date) between p_from and p_to limit 5001)s;

when 'material_usage' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Production','business_date',s.business_date) - 'safe_label' from (select r.id,r.production_id,r.raw_material_id,r.quantity_used,r.standard_usage,r.actual_usage,r.variance_qty,r.variance_percent,r.uom,r.wastage_quantity,'Material usage' safe_label,(r.created_at at time zone 'Asia/Kuala_Lumpur')::date business_date from public.factory_production_material_usage r where ((r.created_at at time zone 'Asia/Kuala_Lumpur')::date) between p_from and p_to limit 5001)s;

when 'material_allocations' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Batch Traceability','business_date',s.business_date) - 'safe_label' from (select r.id,r.production_material_usage_id,r.raw_material_batch_balance_id,r.allocated_qty,'Raw material lineage' safe_label,(r.created_at at time zone 'Asia/Kuala_Lumpur')::date business_date from public.factory_production_material_usage_batch_allocations r where ((r.created_at at time zone 'Asia/Kuala_Lumpur')::date) between p_from and p_to limit 5001)s;

when 'finished_goods' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Warehouse','business_date',s.business_date) - 'safe_label' from (select r.id,r.product_code,r.product_name,r.product_name_en,r.category_id,r.product_family_id,r.variant_name,r.uom,r.current_balance,r.min_stock_level,r.status,r.pack_size_qty,r.pack_size_uom,r.base_qty,r.base_uom,r.packaging_type,r.shelf_life_days,r.storage_location_id,r.product_name safe_label,null::date business_date from public.factory_finished_goods r  limit 5001)s;

when 'finished_batches' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Warehouse','business_date',s.business_date) - 'safe_label' from (select r.id,r.finished_good_id,r.production_id,r.source_type,r.batch_no,r.manufacturing_date,r.expiry_date,r.storage_location_id,r.opening_qty,r.current_balance,r.origin_batch_balance_id,r.batch_no safe_label,r.manufacturing_date business_date from public.factory_finished_good_batch_balances r where (r.manufacturing_date) between p_from and p_to limit 5001)s;

when 'dispatches' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Warehouse','business_date',s.business_date) - 'safe_label' from (select r.id,r.dispatch_no,r.dispatch_date,r.status,r.completed_at,r.cancelled_at,r.reversed_at,r.customer_id,r.dispatch_no safe_label,r.dispatch_date business_date from public.factory_finished_good_dispatches r where (r.dispatch_date) between p_from and p_to limit 5001)s;

when 'dispatch_items' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Warehouse','business_date',s.business_date) - 'safe_label' from (select r.id,r.dispatch_id,r.finished_good_id,r.quantity,r.batch_no,r.batch_no safe_label,(r.created_at at time zone 'Asia/Kuala_Lumpur')::date business_date from public.factory_finished_good_dispatch_items r where ((r.created_at at time zone 'Asia/Kuala_Lumpur')::date) between p_from and p_to limit 5001)s;

when 'dispatch_allocations' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Warehouse','business_date',s.business_date) - 'safe_label' from (select r.id,r.dispatch_item_id,r.production_id,r.quantity,r.batch_no,r.manufacturing_date,r.expiry_date,r.storage_location_id,r.batch_balance_id,r.batch_no safe_label,(r.created_at at time zone 'Asia/Kuala_Lumpur')::date business_date from public.factory_finished_good_dispatch_batch_allocations r where ((r.created_at at time zone 'Asia/Kuala_Lumpur')::date) between p_from and p_to limit 5001)s;

when 'product_movements' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Warehouse','business_date',s.business_date) - 'safe_label' from (select r.id,r.finished_good_id,r.movement_type,r.quantity,r.uom,r.movement_date,r.finished_good_batch_balance_id,r.internal_transfer_id,r.movement_type safe_label,r.movement_date business_date from public.factory_product_stock_movements r where (r.movement_date) between p_from and p_to limit 5001)s;

when 'product_stock_checks' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Warehouse','business_date',s.business_date) - 'safe_label' from (select r.id,r.check_no,r.check_date,r.status,r.submitted_at,r.approved_at,r.check_no safe_label,r.check_date business_date from public.factory_product_stock_checks r where (r.check_date) between p_from and p_to limit 5001)s;

when 'product_stock_counts' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Warehouse','business_date',s.business_date) - 'safe_label' from (select r.id,r.stock_check_id,r.finished_good_id,r.system_qty,r.physical_qty,r.variance_qty,r.variance_percent,r.count_status,r.variance_status,r.uom,'Product stock counts' safe_label,(r.created_at at time zone 'Asia/Kuala_Lumpur')::date business_date from public.factory_product_stock_check_items r where ((r.created_at at time zone 'Asia/Kuala_Lumpur')::date) between p_from and p_to limit 5001)s;

when 'internal_transfers' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Warehouse','business_date',s.business_date) - 'safe_label' from (select r.id,r.transfer_no,r.inventory_type,r.from_location_id,r.to_location_id,r.transfer_date,r.status,r.completed_at,r.transfer_no safe_label,r.transfer_date business_date from public.factory_internal_transfers r where (r.transfer_date) between p_from and p_to limit 5001)s;

when 'transfer_items' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Warehouse','business_date',s.business_date) - 'safe_label' from (select r.id,r.transfer_id,r.raw_material_id,r.finished_good_id,r.quantity,r.uom,r.source_raw_material_batch_balance_id,r.destination_raw_material_batch_balance_id,r.source_finished_good_batch_balance_id,r.destination_finished_good_batch_balance_id,'Transfer items' safe_label,(r.created_at at time zone 'Asia/Kuala_Lumpur')::date business_date from public.factory_internal_transfer_items r where ((r.created_at at time zone 'Asia/Kuala_Lumpur')::date) between p_from and p_to limit 5001)s;

when 'raw_materials' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Raw Materials','business_date',s.business_date) - 'safe_label' from (select r.id,r.material_code,r.name,r.name_en,r.category_id,r.uom,r.current_balance,r.min_stock_level,r.status,r.expiry_tracking_mode,r.shelf_life_days,r.par_level,r.storage_location_id,r.conversion_package_quantity,r.conversion_base_uom,r.name safe_label,null::date business_date from public.factory_raw_materials r  limit 5001)s;

when 'raw_batches' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Raw Materials','business_date',s.business_date) - 'safe_label' from (select r.id,r.receiving_item_id,r.raw_material_id,r.source_type,r.internal_batch_no,r.supplier_lot_no,r.received_date,r.manufacturing_date,r.expiry_date,r.storage_location_id,r.uom,r.opening_qty,r.current_balance,r.status,r.origin_batch_balance_id,r.internal_batch_no safe_label,r.received_date business_date from public.factory_raw_material_batch_balances r where (r.received_date) between p_from and p_to limit 5001)s;

when 'receipts' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Raw Materials','business_date',s.business_date) - 'safe_label' from (select r.id,r.batch_no,r.received_date,r.status,r.verification_status,r.completed_at,r.cancelled_at,r.verified_at,r.supplier_id,r.batch_no safe_label,r.received_date business_date from public.factory_raw_material_receiving_batches r where (r.received_date) between p_from and p_to limit 5001)s;

when 'receiving_items' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','Raw Materials','business_date',s.business_date) - 'safe_label' from (select r.id,r.batch_id,r.receipt_no,r.raw_material_id,r.supplier_id,r.received_qty,r.uom,r.received_date,r.manufacturing_date,r.expiry_date,r.expiry_source,r.expiry_confirmed,r.storage_location_id,r.supplier_lot_no,r.internal_batch_no,r.receipt_no safe_label,r.received_date business_date from public.factory_raw_material_receivings r where (r.received_date) between p_from and p_to limit 5001)s;

