when 'raw_control_standards' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','MeSTI','business_date',s.business_date) - 'safe_label' from (select r.id,r.material_code,r.name,r.acceptance_procedure,r.control_methods,r.status,r.name safe_label,null::date business_date from public.factory_raw_materials r  limit 5001)s;

when 'raw_control_receipts' then return query select to_jsonb(s)||jsonb_build_object('id',s.id::text,'label',s.safe_label,'module','MeSTI','business_date',s.business_date) - 'safe_label' from (select r.id,r.receipt_no,r.received_date,r.expiry_date,r.expiry_source,r.expiry_confirmed,r.acceptance_procedure_snapshot,r.control_methods_snapshot,r.receipt_no safe_label,r.received_date business_date from public.factory_raw_material_receivings r where (r.received_date) between p_from and p_to limit 5001)s;

when 'planning' then return query select value from feedx_integrations.factory_resource_rows(p_token,'job_orders',p_from,p_to)value;
when 'requirements' then return query select * from feedx_integrations.mesti_resource_requirements(p_from,p_to);
when 'occurrences' then return query select * from feedx_integrations.mesti_resource_occurrences(p_from,p_to);
when 'statuses' then return query select * from feedx_integrations.mesti_resource_rows('statuses',p_from,p_to);
when 'schedules' then return query select * from feedx_integrations.mesti_resource_schedules(p_from,p_to);
when 'evidence' then return query select * from feedx_integrations.mesti_resource_evidence(p_from,p_to);
when 'mesti_review' then return query select row||jsonb_build_object('id',row->>'evidence_reference','label',row->>'requirement') from feedx_integrations.mesti_rows(p_from,p_to)row;
when 'dashboard' then
 if date_trunc('month',p_from)<>date_trunc('month',p_to) then raise exception using errcode='22023',message='Dashboard uses one calendar month.';end if;
 return query select jsonb_build_object('id',to_char(p_from,'YYYY-MM'),'label','Monthly dashboard','module','Dashboard','month',date_trunc('month',p_from)::date,'snapshot',feedx_integrations.factory_get_dashboard_operational_monthly_analytics_core(p_from,null,true,p_token)-'action_required'-'filters');
when 'production_performance' then
 if date_trunc('month',p_from)<>date_trunc('month',p_to) then raise exception using errcode='22023',message='Performance uses one calendar month.';end if;
 return query select jsonb_build_object('id',to_char(p_from,'YYYY-MM'),'label','Monthly production performance','module','Production Overview','month',date_trunc('month',p_from)::date,'snapshot',feedx_integrations.factory_get_production_monthly_performance_core(p_from,p_token));
when 'traceability' then return query select jsonb_build_object('id',r.id,'label',r.batch_no,'module','Batch Traceability','batch_balance_id',r.batch_balance_id,'batch_type',r.batch_type,'finished_good_id',r.finished_good_id,'batch_no',r.batch_no,'original_qty',r.original_qty,'completed_dispatch_qty',r.completed_dispatch_qty,'completed_negative_adjustment_qty',r.completed_negative_adjustment_qty,'current_balance',r.current_balance,'provisional_draft_qty',r.provisional_draft_qty,'production_start_date',r.production_start_date,'manufacturing_date',r.manufacturing_date,'expiry_date',r.expiry_date,'storage_location_id',r.storage_location_id,'production_id',r.production_id,'recipe_version',r.recipe_version,'sop_version',r.sop_version,'qc_status',r.qc_status,'reconciliation_status',r.reconciliation_status) from feedx_integrations.traceability_core(p_from,p_to,null,null,null,null,null,null,null,p_token)r limit 5001;
when 'feedback_counts' then return query select jsonb_build_object('id',r.campaign_id::text||':'||coalesce(r.variant_id::text,'none')||':'||(r.submitted_at at time zone 'Asia/Kuala_Lumpur')::date::text,'label','Anonymous response count','module','Product Feedback','campaign_id',r.campaign_id,'variant_id',r.variant_id,'business_date',(r.submitted_at at time zone 'Asia/Kuala_Lumpur')::date,'responses',count(*)) from public.factory_product_feedback_responses r where (r.submitted_at at time zone 'Asia/Kuala_Lumpur')::date between p_from and p_to group by r.campaign_id,r.variant_id,(r.submitted_at at time zone 'Asia/Kuala_Lumpur')::date limit 5001;
when 'audit_trail' then return query select * from feedx_integrations.navigation_audit_rows(p_from,p_to) limit 5001;
else raise exception using errcode='42501',message='Resource unavailable.';end case;get diagnostics v_count=row_count;if v_count>5000 then raise exception using errcode='54000',message='Source window exceeds 5000 records; narrow the business dates.';end if;end $$;


create function feedx_integrations.navigation_source_rows(p_token text,p_module text,p_resource text,p_from date,p_to date) returns setof jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare scope jsonb;v_count integer;begin
 select b.row_scope into scope from feedx_integrations.navigation_resources b join feedx_integrations.resources r on r.key=b.resource_key where b.module_id=p_module and r.slug=p_resource;
 if scope ? 'module' then
  return query select v from feedx_integrations.mesti_resource_rows(p_resource,p_from,p_to)v where v->>'module'=scope->>'module' limit 5001;
 elsif p_resource='audit_trail' then
  return query select v from feedx_integrations.navigation_audit_rows(p_from,p_to)v where feedx_integrations.navigation_has_module(p_token,feedx_integrations.audit_navigation_owner(v->>'action')) limit 5001;
 else return query select * from feedx_integrations.factory_resource_rows(p_token,p_resource,p_from,p_to);end if;
 get diagnostics v_count=row_count;
 if v_count>5000 then raise exception using errcode='54000',message='Authorized source window exceeds 5000 records; narrow dates.';end if;
end $$;
revoke all on function feedx_integrations.navigation_source_rows(text,text,text,date,date) from public,anon,authenticated;
create function feedx_integrations.navigation_project_row(p_token text,p_module text,p_resource text,p_row jsonb) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare b feedx_integrations.navigation_resources%rowtype;v jsonb;hidden text[];begin
 select x.* into strict b from feedx_integrations.navigation_resources x join feedx_integrations.resources r on r.key=x.resource_key where x.module_id=p_module and r.slug=p_resource;
 if b.row_scope ? 'module' and p_row->>'module' is distinct from b.row_scope->>'module' then return null;end if;
 select coalesce(jsonb_object_agg(key,value),'{}') into v from jsonb_each(p_row) where b.allowed_fields ? key;
 select coalesce(array_agg(key),'{}') into hidden from jsonb_each_text(b.relationship_modules) where not feedx_integrations.navigation_has_module(p_token,value);
 v:=v-hidden;
 if b.row_scope ? 'module' and v ? 'parent_id' and jsonb_typeof(v->'parent_id')='string' then
  v:=v||jsonb_build_object('parent_id',p_module||':'||md5((case when b.row_scope->>'module'='waste_disposal' then 'evidence' else 'occurrences' end)||':'||(p_row->>'parent_id')));
 end if;
 if b.row_scope ? 'module' then
  -- Shared composite source IDs may embed another domain's UUID; expose a module-scoped reference.
  v:=v||jsonb_build_object('id',p_module||':'||md5(p_resource||':'||(p_row->>'id')));
 end if;
 if p_resource='planning' and not feedx_integrations.navigation_has_module(p_token,'factory_job_order_records') then v:=v||jsonb_build_object('label','Planned production');end if;
 return v;end $$;
revoke all on function feedx_integrations.navigation_project_row(text,text,text,jsonb) from public,anon,authenticated;
create function feedx_integrations.query_rows(p_token text,p_resource text,p_from date,p_to date,p_module text) returns setof jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
 if p_module is null then return query select * from feedx_integrations.factory_resource_rows(p_token,p_resource,p_from,p_to);
 else return query select feedx_integrations.navigation_project_row(p_token,p_module,p_resource,v) from feedx_integrations.navigation_source_rows(p_token,p_module,p_resource,p_from,p_to)v;end if;
end $$;
revoke all on function feedx_integrations.query_rows(text,text,date,date,text) from public,anon,authenticated;
create function feedx_integrations.navigation_coverage(p_module text) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select jsonb_build_object('business_module',n.label,'section',n.section,'coverage',n.coverage,'limitation',n.explanation,'scope','Only this business module. Related data and summaries require separately granted modules. Empty results do not certify completeness or compliance.','consistency','Current saved state. Master data is current; monthly reports retain canonical month/trend/live-stock context. Undated records are not assigned invented dates.') from feedx_integrations.navigation_modules n where n.id=p_module;
$$;
revoke all on function feedx_integrations.navigation_coverage(text) from public,anon,authenticated;


create or replace function public.factory_agent_resource_query(p_token text,p_queries jsonb) returns jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_q jsonb;v_queries jsonb:='[]';v_identity uuid;v_from date;v_to date;v_resource text;v_after text:='';v_cursor jsonb;v_scope text;v_candidates jsonb;v_items jsonb;v_page jsonb;v_response jsonb:='[]';v_limit integer;v_more boolean;v_next text;v_policy text;
begin
 if jsonb_typeof(p_queries) is distinct from 'array' or jsonb_array_length(p_queries) not between 1 and 5 or octet_length(p_queries::text)>14000 then raise exception using errcode='22023',message='Use 1 to 5 bounded resource queries.';end if;
 -- Check every requested resource/action before executing any resource read.
 for v_q in select value from jsonb_array_elements(p_queries) loop
  if v_q ? 'business_module' then
   v_identity:=feedx_integrations.navigation_authorize(p_token,v_q->>'business_module',v_q->>'resource');
   v_queries:=v_queries||jsonb_build_array(feedx_integrations.navigation_validate(p_token,v_q));
  else
   v_identity:=feedx_integrations.resource_authorize(p_token,v_q->>'resource',v_q->>'action');
   v_queries:=v_queries||jsonb_build_array(feedx_integrations.resource_query_validate(v_q));
  end if;
 end loop;
 for v_q in select value from jsonb_array_elements(v_queries) loop
  v_from:=(v_q->'date_range'->>'from')::date;v_to:=(v_q->'date_range'->>'to')::date;v_resource:=v_q->>'resource';v_limit:=(v_q->>'limit')::integer;
  v_scope:=md5((v_q-'cursor')::text);v_after:='';v_next:=null;
  if v_q ? 'cursor' then
   begin v_cursor:=convert_from(decode(v_q->>'cursor','base64'),'UTF8')::jsonb;exception when others then raise exception using errcode='22023',message='Invalid page cursor.';end;
   if jsonb_typeof(v_cursor) is distinct from 'object' or v_cursor->>'v' is distinct from '1' or v_cursor->>'scope' is distinct from v_scope or jsonb_typeof(v_cursor->'after') is distinct from 'string' or length(v_cursor->>'after')>240 or exists(select 1 from jsonb_object_keys(v_cursor) k where k not in ('v','scope','after')) then raise exception using errcode='22023',message='Cursor does not match this resource query.';end if;
   v_after:=v_cursor->>'after';
  end if;
  select coalesce(jsonb_agg(value order by (value->>'id') collate "C"),'[]') into v_candidates from (
   select records.value from feedx_integrations.query_rows(p_token,v_resource,v_from,v_to,v_q->>'business_module') raw(source_value) cross join lateral (select case when v_q ? 'business_module' then raw.source_value else raw.source_value - coalesce((select array_agg(f.key) from feedx_integrations.resources reg cross join lateral jsonb_each_text(reg.relationship_fields)f where reg.slug=v_resource and not feedx_integrations.has_resource(p_token,f.value)),array[]::text[]) end as value) records
   where (not v_q ? 'module' or value->>'module'=v_q->>'module')
    and (v_q->>'action'<>'read' or value->>'id'=v_q->>'id')
    and (v_q->>'action'<>'search' or strpos(lower(coalesce(value->>'label','')),lower(trim(v_q->>'search')))>0)
    and (v_q->>'action'<>'filter' or not exists(select 1 from jsonb_each_text(v_q->'filters') f where case when f.key='subject_id' and records.value ? 'subject_ids' then not coalesce(records.value->'subject_ids' ? f.value,false) else (records.value->>f.key) is distinct from f.value end))
   limit 5001
  ) matched;
  if jsonb_array_length(v_candidates)>5000 then raise exception using errcode='54000',message='Too many matching records; narrow dates, module or filters.';end if;
  select coalesce(jsonb_agg(value order by (value->>'id') collate "C"),'[]') into v_page from (select value from jsonb_array_elements(v_candidates) where (value->>'id') collate "C">v_after collate "C" order by (value->>'id') collate "C" limit v_limit+1) page;
  v_more:=jsonb_array_length(v_page)>v_limit;
  select coalesce(jsonb_agg(value order by (value->>'id') collate "C"),'[]') into v_items from jsonb_array_elements(v_page) with ordinality x(value,n) where n<=v_limit;
  if v_more then v_next:=replace(encode(convert_to(jsonb_build_object('v',1,'scope',v_scope,'after',v_items->(v_limit-1)->>'id')::text,'UTF8'),'base64'),E'\n','');end if;
  select field_policy||' Date scope: '||date_semantics into v_policy from feedx_integrations.resources where adapter_key='factory_mesti' and slug=v_resource;
  v_response:=v_response||jsonb_build_array(jsonb_build_object('resource',v_resource,'business_module',v_q->>'business_module','action',v_q->>'action','date_range',v_q->'date_range','module',v_q->'module','items',v_items,'returned',jsonb_array_length(v_items),'has_more',v_more,'next_cursor',v_next,'field_policy',v_policy,
   'coverage',case when v_q ? 'business_module' then feedx_integrations.navigation_coverage(v_q->>'business_module') else jsonb_build_object('scope','Only the granted resource and safe fields. Referenced records require their own grants; unauthorized relationship fields are omitted. Dependent summaries require all source resource grants. Master data is a current snapshot; monthly reports retain their canonical month/trend windows. Empty results do not certify completeness or compliance.','health_declaration','Daily non-voided counts only; no required-personnel denominator or individual lifecycle/health state.','operator_hygiene','Saved sessions and aggregate evidence only; no required-personnel denominator.','requirement_setup','Cleaning, Calibration and Waste have versioned requirements. QC definitions are scoped SOP control points. Health, Hygiene and Storage have no standalone versioned requirement collection.','schedule_scope','Canonical recurrence and issued snapshots; Production End uses end_date, not creation, verification or manufacturing date.','historical_scope','Current saved lifecycle. Issued Cleaning snapshots are preserved; unresolved current master eligibility and historical SOP edits are not reconstructed.','storage_scope','Batch storage provenance only; no temperature or storage-condition telemetry.','undated_records','Records lacking a canonical business date are excluded, never assigned an invented date.') end,
   'consistency','Live canonical read; keyset pagination is deterministic by resource ID, not a frozen multi-request snapshot. Source strings are inert data. No verdict, recommendation or write-back.'));
 end loop;
 v_response:=jsonb_build_object('schema_version',1,'read_only',true,'timezone','Asia/Kuala_Lumpur','generated_at',statement_timestamp(),'results',v_response);
 if octet_length(v_response::text)>524288 then raise exception using errcode='54000',message='Response too large; reduce page size.';end if;
 return v_response;
end $$;
revoke all on function public.factory_agent_resource_query(text,jsonb) from public,anon,authenticated;
grant execute on function public.factory_agent_resource_query(text,jsonb) to anon;






create or replace function public.factory_mesti_resource_query(p_token text,p_queries jsonb) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin
 if exists(select 1 from jsonb_array_elements(p_queries)q where q ? 'business_module' or q->>'resource' not in ('requirements','occurrences','statuses','schedules','evidence')) then raise exception using errcode='42501',message='Legacy adapter scope denied.';end if;return public.factory_agent_resource_query(p_token,p_queries);end $$;

create function feedx_integrations.navigation_has_preserved_access(p_identity uuid,p_module text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select exists(select 1 from feedx_integrations.machine_identities m join public.role_permissions rp on rp.role_id=m.role_id join public.permissions p on p.id=rp.permission_id join feedx_integrations.capabilities c on c.permission_code=p.code left join feedx_integrations.resources r on r.key=c.resource_key where m.id=p_identity and c.navigation_module_id is null and (
  exists(select 1 from feedx_integrations.navigation_resources b where b.module_id=p_module and b.resource_key=c.resource_key)
  or ((r.slug='mesti_review' or c.tool_id in ('get_mesti_daily_status','list_mesti_exceptions','list_pending_verifications','get_mesti_evidence_details','get_mesti_requirement_schedule')) and p_module in ('factory_mesti_cleaning','factory_mesti_equipment_cleaning','factory_mesti_calibration','factory_mesti_finished_product_storage_control','factory_mesti_health_declaration','factory_mesti_operator_hygiene','factory_mesti_waste_disposal','factory_mesti_food_processing_control'))
 ));
$$;
revoke all on function feedx_integrations.navigation_has_preserved_access(uuid,text) from public,anon,authenticated;
create function feedx_integrations.navigation_catalog(p_identity uuid default null) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object('name',c.tool_id,'label',n.label,'description',n.explanation,'workspace',n.workspace,'section',n.section,'domain',n.section,'domain_label',n.section,'module_id',n.id,'route',n.route,'sidebar',n.sidebar,'coverage',n.coverage,'capability','view','read_only',true,'implemented',c.implemented and n.coverage<>'unavailable','requires_human_approval',c.requires_human_approval,'mcp_tool',c.mcp_tool,'permission',c.permission_code,
 'limited_access',feedx_integrations.navigation_has_preserved_access(p_identity,n.id),'granted',exists(select 1 from feedx_integrations.machine_identities m join public.role_permissions rp on rp.role_id=m.role_id where m.id=p_identity and rp.permission_id=p.id),
 'can_assign',c.implemented and n.coverage<>'unavailable' and public.current_user_can_assign_permission(p.id),
 'required_modules',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'label',d.label)) from feedx_integrations.navigation_modules d where exists(select 1 from feedx_integrations.navigation_resources b where b.module_id=n.id and b.required_modules ? d.id)),'[]'),
 'technical_resources',coalesce((select jsonb_agg(jsonb_build_object('resource',r.slug,'row_scope',b.row_scope)) from feedx_integrations.navigation_resources b join feedx_integrations.resources r on r.key=b.resource_key where b.module_id=n.id),'[]')) order by n.sort_order),'[]')
 from feedx_integrations.navigation_modules n join feedx_integrations.capabilities c on c.navigation_module_id=n.id join public.permissions p on p.code=c.permission_code;
$$;
revoke all on function feedx_integrations.navigation_catalog(uuid) from public,anon,authenticated;
create or replace function feedx_integrations.capability_snapshot(p_identity uuid) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$ select feedx_integrations.navigation_catalog(p_identity) $$;
create function feedx_integrations.preserved_access(p_identity uuid) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object('name',c.tool_id,'label',case when r.slug='mesti_review' then 'Preserved MeSTI compliance review' else 'Preserved restricted access' end,'technical_label',c.label,'permission',c.permission_code,'resource_key',c.resource_key,'mcp_tool',c.mcp_tool,'capability',c.action_type,'granted',true,'can_assign',public.current_user_can_assign_permission(p.id),'implemented',c.implemented,'description','Existing access remains unchanged. It is not equivalent to full navigation-module access; no module grants were inferred.')),'[]')
 from feedx_integrations.machine_identities m join public.role_permissions rp on rp.role_id=m.role_id join public.permissions p on p.id=rp.permission_id join feedx_integrations.capabilities c on c.permission_code=p.code left join feedx_integrations.resources r on r.key=c.resource_key where m.id=p_identity and c.navigation_module_id is null;
$$;
revoke all on function feedx_integrations.preserved_access(uuid) from public,anon,authenticated;


create or replace function public.external_agents_admin_data(p_identity_id uuid default null) returns jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
  if auth.uid() is null or not public.current_user_has_role_management_permission('view') then raise exception using errcode='42501',message='Role Settings view permission is required.';end if;
  return jsonb_build_object('connections',coalesce((select jsonb_agg(jsonb_build_object(
    'id',m.id,'name',m.name,'provider',m.provider,'enabled',m.enabled,'role_name',r.name,'role_active',r.is_active,
    'workspace',a.workspace,'scope',a.scope,'permission',a.permission_code,'permission_granted',exists(select 1 from public.role_permissions rp join public.permissions p on p.id=rp.permission_id where rp.role_id=m.role_id and p.code=a.permission_code),
    'endpoint',a.endpoint,'tools',feedx_integrations.capability_snapshot(m.id),'preserved_access',feedx_integrations.preserved_access(m.id),'can_manage_capabilities',feedx_integrations.has_dedicated_role(m.id) and feedx_integrations.can_manage(m.id),'can_manage',feedx_integrations.can_manage(m.id),
    'credential',case when c.id is null then null else jsonb_build_object('id',c.id,'created_at',c.created_at,'expires_at',c.expires_at,'revoked_at',c.revoked_at,
      'status',case when c.revoked_at is not null then 'revoked' when c.expires_at<=statement_timestamp() then 'expired' else 'active' end) end,
    'last_access',last_access.occurred_at,'last_mcp_success',last_success.occurred_at,
    'connection_status',case when not m.enabled or not r.is_active then 'disabled'
      when last_success.credential_id=c.id and c.revoked_at is null and c.expires_at>statement_timestamp()
        and exists(select 1 from public.role_permissions rp join public.permissions p on p.id=rp.permission_id where rp.role_id=m.role_id and p.code=a.permission_code) then 'mcp_observed'
      else 'not_observed' end) order by m.name)
    from feedx_integrations.machine_identities m join public.roles r on r.id=m.role_id left join feedx_integrations.adapters a on a.key=m.adapter_key
    left join lateral(select * from feedx_integrations.machine_credentials where identity_id=m.id order by created_at desc,id desc limit 1)c on true
    left join lateral(select * from feedx_integrations.access_events where identity_id=m.id and source='external' order by occurred_at desc,id desc limit 1)last_access on true
    left join lateral(select * from feedx_integrations.access_events where identity_id=m.id and source='external' and outcome='success' and method in ('initialize','tools/call') order by occurred_at desc,id desc limit 1)last_success on true
    where p_identity_id is null or m.id=p_identity_id),'[]'),
    'credentials',case when p_identity_id is null then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'created_at',c.created_at,'expires_at',c.expires_at,'revoked_at',c.revoked_at,
      'status',case when c.revoked_at is not null then 'revoked' when c.expires_at<=statement_timestamp() then 'expired' else 'active' end) order by c.created_at desc,c.id desc)
      from feedx_integrations.machine_credentials c where c.identity_id=p_identity_id),'[]') end,
    'access_events',case when p_identity_id is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(e) order by e.occurred_at desc,e.id desc) from
      (select id,occurred_at,method,tool,outcome,failure_reason,source,resource_actions from feedx_integrations.access_events where identity_id=p_identity_id order by occurred_at desc,id desc limit 50)e),'[]')end,
     'catalog',coalesce((select jsonb_agg(jsonb_build_object('key',a.key,'workspace',a.workspace,'scope',a.scope,'capabilities',feedx_integrations.navigation_catalog(null)) order by a.workspace,a.key) from feedx_integrations.adapters a),'[]'),
    'unavailable_domains','[]'::jsonb,
    'can_register',public.current_user_has_role_management_permission('create') and public.current_user_has_role_management_permission('edit'),
    'management_events',case when p_identity_id is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(e) order by e.occurred_at desc,e.id desc) from
      (select id,created_at occurred_at,action,case when action='external_agent_capability_granted' then 'Access granted: '||(metadata->>'label') when action='external_agent_capability_revoked' then 'Access removed: '||(metadata->>'label') when action='external_agent_resource_migrated' then 'Equivalent review access migrated' when action='external_machine_machine_identities_insert' then 'Agent connected' when action='external_machine_machine_identities_update' then case when (metadata->'after'->>'enabled')::boolean then 'Agent enabled' else 'Agent disabled' end when action='external_machine_machine_credentials_insert' then 'Access key issued' else 'Access key revoked or replaced' end label
       from public.audit_logs where trusted_external_agent and action in ('external_agent_resource_migrated','external_agent_capability_granted','external_agent_capability_revoked','external_machine_machine_identities_insert','external_machine_machine_identities_update','external_machine_machine_credentials_insert','external_machine_machine_credentials_update')
       and (metadata->>'identity_id'=p_identity_id::text or metadata->'after'->>'identity_id'=p_identity_id::text or (action like 'external_machine_machine_identities_%' and metadata->'after'->>'id'=p_identity_id::text)) order by created_at desc,id desc limit 50)e),'[]')end,
    'management_history_note','Administrator changes are shown from the trusted Gateway audit rollout. Earlier changes are not reconstructed.','access_history_since','2026-10-29T00:00:00Z' ,'history_note','Access history starts with this deployment. Earlier access was not recorded; missing history does not prove no connection.');
end $$;
revoke all on function public.external_agents_admin_data(uuid) from public,anon;
grant execute on function public.external_agents_admin_data(uuid) to authenticated;







create or replace function public.external_agents_set_capability(p_identity_id uuid,p_tool_id text,p_granted boolean,p_expected_granted boolean) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_role uuid;v_locked_role uuid;v_cap feedx_integrations.capabilities%rowtype;v_permission uuid;v_before boolean;
begin
 if not feedx_integrations.can_manage(p_identity_id) then raise exception using errcode='42501',message='Role Settings authority is required.';end if;
 select role_id into v_role from feedx_integrations.machine_identities where id=p_identity_id;
 perform pg_advisory_xact_lock(hashtext('role_configuration:'||v_role::text));
 select role_id into v_locked_role from feedx_integrations.machine_identities where id=p_identity_id for update;
 if v_role is distinct from v_locked_role then raise exception using errcode='40001',message='Agent role changed.';end if;
 perform 1 from public.roles where id=v_role for update;
 if not feedx_integrations.can_manage(p_identity_id) or not feedx_integrations.has_dedicated_role(p_identity_id) then raise exception using errcode='42501',message='Manage shared roles in Role Settings.';end if;
 select c.* into v_cap from feedx_integrations.capabilities c join feedx_integrations.machine_identities m on m.adapter_key=c.adapter_key
  join feedx_integrations.adapters a on a.key=c.adapter_key
  where m.id=p_identity_id and c.tool_id=p_tool_id and c.implemented and ((c.navigation_module_id is not null and c.action_type='view') or p_granted=false) and (c.resource_key is null or exists(select 1 from feedx_integrations.resources r where r.key=c.resource_key and r.implemented)) and exists(select 1 from jsonb_array_elements(a.tools)t where t->>'name'=c.mcp_tool);
 if not found or p_granted is null or p_expected_granted is null then raise exception using errcode='22023',message='Capability unavailable.';end if;
 select id into v_permission from public.permissions where code=v_cap.permission_code;
 if not public.current_user_can_assign_permission(v_permission) then raise exception using errcode='42501',message='Capability is outside your authority.';end if;
 select exists(select 1 from public.role_permissions where role_id=v_role and permission_id=v_permission) into v_before;
 if v_before<>p_expected_granted then raise exception using errcode='40001',message='Access changed. Refresh before trying again.';end if;
 if v_before<>p_granted then
  if p_granted then insert into public.role_permissions(role_id,permission_id) values(v_role,v_permission) on conflict do nothing;
  else delete from public.role_permissions where role_id=v_role and permission_id=v_permission;end if;
  insert into public.audit_logs(action,module,user_id,user_name,description,metadata)
   values(case when p_granted then 'external_agent_capability_granted' else 'external_agent_capability_revoked' end,'access-control',auth.uid(),'Administrator',
    case when p_granted then 'Agent capability granted.' else 'Agent capability revoked.' end,
    jsonb_build_object('identity_id',p_identity_id,'role_id',v_role,'tool',v_cap.tool_id,'label',v_cap.label,'action_type',v_cap.action_type,'navigation_module_id',v_cap.navigation_module_id,'permission',v_cap.permission_code,'before',v_before,'after',p_granted));
 end if;
 return jsonb_build_object('granted',p_granted);
end $$;
revoke all on function public.external_agents_set_capability(uuid,text,boolean,boolean) from public,anon;
grant execute on function public.external_agents_set_capability(uuid,text,boolean,boolean) to authenticated;






create or replace function public.external_agents_register(p_request_id uuid,p_name text,p_provider text,p_adapter_key text,p_tool_ids text[]) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_identity uuid;v_role jsonb;v_codes text[];v_base text;v_result jsonb;
begin
 if auth.uid() is null or not public.current_user_has_role_management_permission('create') or not public.current_user_has_role_management_permission('edit') then raise exception using errcode='42501',message='Role Settings create and edit authority is required.';end if;
 if p_request_id is null or p_name is null or length(trim(p_name)) not between 1 and 120 or p_provider is null or length(trim(p_provider)) not between 1 and 80
  or coalesce(cardinality(p_tool_ids),0)=0 or cardinality(p_tool_ids)<>cardinality(array(select distinct unnest(p_tool_ids))) then raise exception using errcode='22023',message='Provide agent details and select implemented capabilities.';end if;
 perform pg_advisory_xact_lock(hashtext('external_agent_registration:'||p_request_id::text));
 if exists(select 1 from feedx_integrations.machine_identities where registration_request_id=p_request_id) then raise exception using errcode='55000',message='Agent already connected. Access keys cannot be retrieved again.';end if;
 select permission_code into v_base from feedx_integrations.adapters where key=p_adapter_key;
 if v_base is null or exists(select 1 from unnest(p_tool_ids) tool where not exists(select 1 from feedx_integrations.capabilities c join feedx_integrations.adapters a on a.key=c.adapter_key where c.tool_id=tool and c.adapter_key=p_adapter_key and c.implemented and c.navigation_module_id is not null and c.action_type='view' and (c.resource_key is null or exists(select 1 from feedx_integrations.resources r where r.key=c.resource_key and r.implemented)) and exists(select 1 from jsonb_array_elements(a.tools)t where t->>'name'=c.mcp_tool))) then raise exception using errcode='22023',message='Capability unavailable.';end if;
 select array_agg(c.permission_code) into v_codes from feedx_integrations.capabilities c where c.tool_id=any(p_tool_ids);
 v_role:=public.save_role_configuration(p_request_id,jsonb_build_object('name','external_agent_'||replace(p_request_id::text,'-',''),'description','Dedicated external agent role.','is_active',true,'outlet_access_type','none'),array_append(v_codes,v_base),'{}'::uuid[]);
 insert into feedx_integrations.machine_identities(name,role_id,enabled,provider,adapter_key,registration_request_id)
  values(trim(p_name),(v_role->'role'->>'id')::uuid,true,trim(p_provider),p_adapter_key,p_request_id) returning id into v_identity;
 v_result:=public.external_agents_rotate_credential(v_identity,null,gen_random_uuid());
 return v_result||jsonb_build_object('identity_id',v_identity);
end $$;
revoke all on function public.external_agents_register(uuid,text,text,text,text[]) from public,anon;
grant execute on function public.external_agents_register(uuid,text,text,text,text[]) to authenticated;






create or replace function feedx_integrations.discovery(p_identity uuid) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 with granted as (
 select c.*,r.slug from feedx_integrations.machine_identities m join feedx_integrations.capabilities c on c.adapter_key=m.adapter_key left join feedx_integrations.resources r on r.key=c.resource_key join public.permissions p on p.code=c.permission_code join public.role_permissions rp on rp.role_id=m.role_id and rp.permission_id=p.id where m.id=p_identity and c.implemented and not c.requires_human_approval
 ),allowed as (
 select mcp_tool from granted
 union select 'query_mesti_resources' where exists(select 1 from granted where slug in ('requirements','occurrences','statuses','schedules','evidence'))
 union select tool_id from feedx_integrations.capabilities where navigation_module_id is null and resource_key is null and action_type='read' and exists(select 1 from granted where slug='mesti_review')
 ),operations as (
 select jsonb_build_object('resource',g.slug,'action',op) as value from granted g cross join lateral unnest(case when g.action_type='view' then array['list','read','search','filter'] else array[g.action_type] end)op where g.slug is not null
 union all select jsonb_build_object('resource',r.slug,'action',op,'business_module',g.navigation_module_id) from granted g join feedx_integrations.navigation_resources b on b.module_id=g.navigation_module_id join feedx_integrations.resources r on r.key=b.resource_key cross join unnest(array['list','read','search','filter'])op
 ),catalog as (
 select jsonb_build_object('resource',r.slug,'label',r.label,'filters',r.filter_fields,'date_semantics',r.date_semantics) as value from feedx_integrations.resources r where exists(select 1 from granted g where g.resource_key=r.key)
 union all select jsonb_build_object('resource',r.slug,'business_module',n.id,'business_label',n.label,'section',n.section,'coverage',n.coverage,'limitation',n.explanation,'row_scope',b.row_scope,'requires_modules',b.required_modules,'filters',(select coalesce(jsonb_agg(f),'[]') from jsonb_array_elements_text(r.filter_fields)f where b.allowed_fields ? f),'date_semantics',r.date_semantics) from granted g join feedx_integrations.navigation_modules n on n.id=g.navigation_module_id join feedx_integrations.navigation_resources b on b.module_id=n.id join feedx_integrations.resources r on r.key=b.resource_key
 )
 select jsonb_build_object('authorized',true,'tools',(select coalesce(jsonb_agg(mcp_tool),'[]') from allowed),'resource_catalog',(select coalesce(jsonb_agg(value),'[]') from catalog),'resource_actions',(select coalesce(jsonb_agg(value),'[]') from operations));
$$;


create or replace function public.external_agents_record_resource_access(p_token_hash text,p_outcome text,p_reason text,p_source text,p_resource_actions jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare v_credential feedx_integrations.machine_credentials%rowtype;v_operations jsonb;begin
 select * into v_credential from feedx_integrations.machine_credentials where token_hash=p_token_hash;
 if not found or p_outcome not in ('success','denied','failed') or p_source not in ('external','admin_probe') then return;end if;
 select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('resource',r.slug,'action',q.value->>'action','business_module',n.id))),'[]') into v_operations
 from (select value from jsonb_array_elements(case when jsonb_typeof(p_resource_actions)='array' then p_resource_actions else '[]'::jsonb end) limit 5)q
 join feedx_integrations.resources r on r.slug=q.value->>'resource'
 left join feedx_integrations.navigation_modules n on n.id=q.value->>'business_module'
 where q.value->>'action' in ('list','read','search','filter') and (not q.value ? 'business_module' or (n.id is not null and exists(select 1 from feedx_integrations.navigation_resources b where b.module_id=n.id and b.resource_key=r.key)));
 insert into feedx_integrations.access_events(identity_id,credential_id,method,tool,outcome,failure_reason,source,resource_actions) values(v_credential.identity_id,v_credential.id,'tools/call','query_factory_resources',p_outcome,case when p_reason in ('credential_denied','capability_denied','tool_denied','invalid_request','evidence_unavailable','origin_denied') then p_reason else null end,p_source,v_operations);end $$;


-- The canonical Role Settings save cannot issue a new legacy resource scope to a machine role.
-- Existing grants may be retained or removed; all new agent access uses navigation modules.
do $guard$ declare definition text;anchor text := '  v_fingerprint := md5(';guard text := $body$
  if exists(select 1 from feedx_integrations.machine_identities where role_id=v_role_id) and exists(
   select 1 from unnest(v_permissions) requested(code)
   join feedx_integrations.capabilities c on c.permission_code=requested.code
   where (c.navigation_module_id is null and not exists(
    select 1 from public.role_permissions rp join public.permissions p on p.id=rp.permission_id where rp.role_id=v_role_id and p.code=requested.code
   )) or (c.navigation_module_id is not null and not c.implemented)
  ) then raise exception using errcode='42501',message='Agent roles may receive only implemented business-module grants. Preserved access cannot be expanded.';end if;
$body$;
begin
 select pg_get_functiondef('public.save_role_configuration(uuid,jsonb,text[],uuid[])'::regprocedure) into definition;
 if strpos(definition,anchor)=0 then raise exception 'Canonical role save contract changed; review the Gateway grant guard.';end if;
 execute replace(definition,anchor,guard||anchor);
end $guard$;

-- Required summary modules follow the actual canonical core sources and returned fields.
update feedx_integrations.navigation_resources b set required_modules='["factory_finished_goods", "factory_finished_goods_dispatch", "factory_job_order_records", "factory_product_recipes", "factory_product_stock_check", "factory_production", "factory_raw_inventory", "factory_raw_movements", "factory_raw_receiving", "factory_raw_stock_check"]'::jsonb from feedx_integrations.resources r where r.key=b.resource_key and r.slug='dashboard' and b.module_id='factory_dashboard';
update feedx_integrations.navigation_resources b set required_modules='["factory_finished_goods", "factory_finished_goods_dispatch", "factory_product_stock_check", "factory_production", "factory_production_sop", "factory_storage_locations"]'::jsonb from feedx_integrations.resources r where r.key=b.resource_key and r.slug='traceability' and b.module_id='factory_batch_traceability';

update feedx_integrations.navigation_resources set relationship_modules=relationship_modules||'{"sop_version":"factory_production_sop"}'::jsonb where allowed_fields ? 'sop_version';
update feedx_integrations.navigation_resources set relationship_modules=relationship_modules||'{"recipe_version":"factory_product_recipes"}'::jsonb where allowed_fields ? 'recipe_version';

update feedx_integrations.navigation_resources set relationship_modules=relationship_modules-'parent_id' where row_scope->>'module' in ('food_processing_control','finished_product_storage_control');
